package strategy

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// BenchmarkPostCommit measures the full PostCommit hook execution time.
// This is the baseline before introducing a postCommitCache.
//
// Setup: 1 active session with a shadow branch checkpoint, then a commit
// with the Entire-Checkpoint trailer. PostCommit reads HEAD, finds the session,
// runs condensation (filesOverlapWithContent, CondenseSession, carry-forward).
func BenchmarkPostCommit(b *testing.B) {
	b.Run("SingleSession_Active", benchPostCommitSingleSession(session.PhaseActive))
	b.Run("SingleSession_Idle", benchPostCommitSingleSession(session.PhaseIdle))
	b.Run("MultipleSessions_2", benchPostCommitMultipleSessions(2))
	b.Run("MultipleSessions_3", benchPostCommitMultipleSessions(3))
}

func benchPostCommitSingleSession(phase session.Phase) func(*testing.B) {
	return func(b *testing.B) {
		for range b.N {
			b.StopTimer()
			dir := benchSetupPostCommitRepo(b, phase, 1)
			b.Chdir(dir)
			paths.ClearWorktreeRootCache()
			b.StartTimer()

			s := &ManualCommitStrategy{}
			if err := s.PostCommit(context.Background()); err != nil {
				b.Fatalf("PostCommit: %v", err)
			}
		}
	}
}

func benchPostCommitMultipleSessions(sessionCount int) func(*testing.B) {
	return func(b *testing.B) {
		for range b.N {
			b.StopTimer()
			dir := benchSetupPostCommitRepo(b, session.PhaseActive, sessionCount)
			b.Chdir(dir)
			paths.ClearWorktreeRootCache()
			b.StartTimer()

			s := &ManualCommitStrategy{}
			if err := s.PostCommit(context.Background()); err != nil {
				b.Fatalf("PostCommit: %v", err)
			}
		}
	}
}

// benchSetupPostCommitRepo creates a git repo with N sessions that have shadow branch
// checkpoints, then creates a commit with the Entire-Checkpoint trailer.
// Returns the repo directory path, ready for PostCommit() to run.
func benchSetupPostCommitRepo(b *testing.B, phase session.Phase, sessionCount int) string {
	b.Helper()

	dir := b.TempDir()
	// Resolve symlinks (macOS /var -> /private/var)
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	repo, err := git.PlainInit(dir, false)
	if err != nil {
		b.Fatalf("git init: %v", err)
	}

	// Configure git user
	cfg, err := repo.Config()
	if err != nil {
		b.Fatalf("config: %v", err)
	}
	cfg.User.Name = "Bench User"
	cfg.User.Email = "bench@example.com"
	if err := repo.SetConfig(cfg); err != nil {
		b.Fatalf("set config: %v", err)
	}

	// Create initial files and commit
	wt, err := repo.Worktree()
	if err != nil {
		b.Fatalf("worktree: %v", err)
	}

	// Create multiple files to make file overlap checks realistic
	for i := range 5 {
		name := fmt.Sprintf("src/file_%d.go", i)
		abs := filepath.Join(dir, name)
		if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
			b.Fatalf("mkdir: %v", err)
		}
		content := fmt.Sprintf("package main\nfunc f%d() {}\n", i)
		if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
			b.Fatalf("write: %v", err)
		}
		if _, err := wt.Add(name); err != nil {
			b.Fatalf("add: %v", err)
		}
	}

	if _, err := wt.Commit("initial commit", &git.CommitOptions{
		Author: &object.Signature{Name: "Bench", Email: "bench@test.com", When: time.Now()},
	}); err != nil {
		b.Fatalf("commit: %v", err)
	}

	s := &ManualCommitStrategy{}

	// Chdir to repo dir for the entire setup (SaveStep, loadSessionState, etc.
	// all depend on paths.WorktreeRoot() which uses cwd). b.Chdir restores
	// the original directory when the benchmark function returns.
	b.Chdir(dir)
	paths.ClearWorktreeRootCache()

	// Set up each session with a shadow branch checkpoint
	modifiedFiles := []string{"src/file_0.go", "src/file_1.go"}
	for i := range sessionCount {
		sessionID := fmt.Sprintf("bench-session-%d", i)

		// Modify files with agent content
		for _, f := range modifiedFiles {
			abs := filepath.Join(dir, f)
			content := fmt.Sprintf("package main\n// modified by agent session %d\nfunc f() {}\n", i)
			if err := os.WriteFile(abs, []byte(content), 0o644); err != nil {
				b.Fatalf("write: %v", err)
			}
		}

		// Create metadata directory with transcript
		metadataDir := ".entire/metadata/" + sessionID
		metadataDirAbs := filepath.Join(dir, metadataDir)
		if err := os.MkdirAll(metadataDirAbs, 0o755); err != nil {
			b.Fatalf("mkdir: %v", err)
		}
		transcript := `{"type":"human","message":{"content":"implement feature"}}
{"type":"assistant","message":{"content":"I'll implement that for you."}}
`
		if err := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); err != nil {
			b.Fatalf("write transcript: %v", err)
		}

		paths.ClearWorktreeRootCache()

		if err := s.SaveStep(context.Background(), StepContext{
			SessionID:      sessionID,
			ModifiedFiles:  modifiedFiles,
			NewFiles:       []string{},
			DeletedFiles:   []string{},
			MetadataDir:    metadataDir,
			MetadataDirAbs: metadataDirAbs,
			CommitMessage:  "Checkpoint 1",
			AuthorName:     "Bench",
			AuthorEmail:    "bench@test.com",
		}); err != nil {
			b.Fatalf("SaveStep: %v", err)
		}

		// Set the session phase
		state, err := s.loadSessionState(context.Background(), sessionID)
		if err != nil {
			b.Fatalf("load state: %v", err)
		}
		state.Phase = phase
		state.FilesTouched = modifiedFiles
		if err := s.saveSessionState(context.Background(), state); err != nil {
			b.Fatalf("save state: %v", err)
		}
	}

	// Create the user commit with checkpoint trailer (the commit PostCommit will process)
	cpID, err := id.Generate()
	if err != nil {
		b.Fatalf("generate ID: %v", err)
	}

	// Modify a file and commit with trailer
	testFile := filepath.Join(dir, "src/file_0.go")
	if err := os.WriteFile(testFile, []byte("package main\n// modified by agent session 0\nfunc f() {}\n"), 0o644); err != nil {
		b.Fatalf("write: %v", err)
	}
	if _, err := wt.Add("src/file_0.go"); err != nil {
		b.Fatalf("add: %v", err)
	}

	commitMsg := fmt.Sprintf("implement feature\n\n%s: %s\n", trailers.CheckpointTrailerKey, cpID)
	if _, err := wt.Commit(commitMsg, &git.CommitOptions{
		Author: &object.Signature{Name: "Bench", Email: "bench@test.com", When: time.Now()},
	}); err != nil {
		b.Fatalf("commit: %v", err)
	}

	return dir
}

package strategy

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/benchutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

// BenchmarkPrepareCommitMsg measures the full PrepareCommitMsg hook execution time
// at various repo sizes and session counts.
//
// Setup: N files in a git repo, M active sessions with shadow branch checkpoints,
// modified files staged for commit, and a temporary commit message file.
// PrepareCommitMsg reads session states, checks for new content (getStagedFiles,
// transcript comparison, content overlap), extracts the last prompt, and writes
// the checkpoint trailer to the message file.
func BenchmarkPrepareCommitMsg(b *testing.B) {
	b.Run("SmallRepo_1Session", benchPrepareCommitMsg(10, 1))
	b.Run("SmallRepo_3Sessions", benchPrepareCommitMsg(10, 3))
	b.Run("MediumRepo_1Session", benchPrepareCommitMsg(100, 1))
	b.Run("MediumRepo_3Sessions", benchPrepareCommitMsg(100, 3))
	b.Run("LargeRepo_1Session", benchPrepareCommitMsg(500, 1))
	b.Run("LargeRepo_3Sessions", benchPrepareCommitMsg(500, 3))
}

func benchPrepareCommitMsg(fileCount, sessionCount int) func(*testing.B) {
	return func(b *testing.B) {
		// Setup once before the loop — repo creation is expensive and
		// PrepareCommitMsg only mutates COMMIT_EDITMSG on the idle-session + no-TTY path.
		dir, commitMsgFile := benchSetupPrepareCommitMsgRepo(b, fileCount, sessionCount)
		b.Chdir(dir)

		b.ResetTimer()
		for range b.N {
			// Reset only what PrepareCommitMsg mutates
			if err := os.WriteFile(commitMsgFile, []byte("implement feature\n"), 0o644); err != nil {
				b.Fatalf("rewrite commit msg: %v", err)
			}
			paths.ClearWorktreeRootCache()

			s := &ManualCommitStrategy{}
			if err := s.PrepareCommitMsg(context.Background(), commitMsgFile, ""); err != nil {
				b.Fatalf("PrepareCommitMsg: %v", err)
			}
		}
	}
}

// BenchmarkGetStagedFiles measures the isolated cost of getStagedFiles at different
// repo sizes. This is the primary bottleneck: go-git's worktree.Status() scans the
// entire working tree.
func BenchmarkGetStagedFiles(b *testing.B) {
	for _, fileCount := range []int{10, 100, 500} {
		b.Run(fmt.Sprintf("Files_%d", fileCount), func(b *testing.B) {
			// Setup once before the loop — repo creation + staging is expensive.
			br := benchutil.NewBenchRepo(b, benchutil.RepoOpts{FileCount: fileCount})
			b.Chdir(br.Dir)

			// Stage some modifications
			for i := range min(5, fileCount) {
				name := fmt.Sprintf("src/file_%03d.go", i)
				content := benchutil.GenerateGoFile(9000+i, 100)
				br.WriteFile(b, name, content)
				wt, err := br.Repo.Worktree()
				if err != nil {
					b.Fatalf("worktree: %v", err)
				}
				if _, err := wt.Add(name); err != nil {
					b.Fatalf("add: %v", err)
				}
			}

			b.ResetTimer()
			for range b.N {
				paths.ClearWorktreeRootCache()

				if _, err := getStagedFiles(context.Background()); err != nil {
					b.Fatalf("getStagedFiles: %v", err)
				}
			}
		})
	}
}

// benchSetupPrepareCommitMsgRepo creates a git repo with N files, M sessions
// with shadow branch checkpoints, and staged modifications ready for PrepareCommitMsg.
// Returns the repo directory path and the path to the temporary commit message file.
func benchSetupPrepareCommitMsgRepo(b *testing.B, fileCount, sessionCount int) (string, string) {
	b.Helper()

	br := benchutil.NewBenchRepo(b, benchutil.RepoOpts{FileCount: fileCount})

	// Modify and stage files so getStagedFiles returns non-empty
	modifiedFiles := make([]string, 0, min(5, fileCount))
	for i := range min(5, fileCount) {
		modifiedFiles = append(modifiedFiles, fmt.Sprintf("src/file_%03d.go", i))
	}

	// Create sessions with shadow branch checkpoints
	for i := range sessionCount {
		sessionID := fmt.Sprintf("bench-pcm-session-%d", i)

		// Write transcript to metadata dir on disk (for live transcript fallback)
		transcript := benchutil.GenerateTranscript(benchutil.TranscriptOpts{
			MessageCount:    20,
			AvgMessageBytes: 300,
			IncludeToolUse:  true,
			FilesTouched:    modifiedFiles,
		})
		transcriptPath := br.WriteTranscriptFile(b, sessionID, transcript)

		// Seed shadow branch with checkpoint
		br.SeedShadowBranch(b, sessionID, 1, min(5, fileCount))

		// Create session state
		br.CreateSessionState(b, benchutil.SessionOpts{
			SessionID:      sessionID,
			Phase:          session.PhaseIdle,
			StepCount:      1,
			FilesTouched:   modifiedFiles,
			TranscriptPath: transcriptPath,
		})
	}

	// Now stage modifications (after shadow branch seeding, since SeedShadowBranch
	// writes files that overlap with what we stage)
	b.Chdir(br.Dir)
	paths.ClearWorktreeRootCache()

	wt, err := br.Repo.Worktree()
	if err != nil {
		b.Fatalf("worktree: %v", err)
	}
	for _, name := range modifiedFiles {
		content := benchutil.GenerateGoFile(8000, 100)
		br.WriteFile(b, name, content)
		if _, err := wt.Add(name); err != nil {
			b.Fatalf("add %s: %v", name, err)
		}
	}

	// Write temporary commit message file
	commitMsgFile := filepath.Join(br.Dir, ".git", "COMMIT_EDITMSG")

	if err := os.WriteFile(commitMsgFile, []byte("implement feature\n"), 0o644); err != nil {
		b.Fatalf("write commit msg: %v", err)
	}

	// Set ENTIRE_TEST_TTY=0 so hasTTY() returns false (simulates agent subprocess).
	// This avoids interactive TTY prompts during benchmarks.
	b.Setenv("ENTIRE_TEST_TTY", "0")

	return br.Dir, commitMsgFile
}

package perf

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
)

// Span tracks timing for an operation and its substeps.
// A Span is not safe for concurrent use from multiple goroutines.
type Span struct {
	name     string
	start    time.Time
	parent   *Span
	children []*Span
	duration time.Duration
	attrs    []slog.Attr
	ctx      context.Context
	ended    bool
	err      error
}

// Start begins a new span. If ctx already has a span, the new one becomes a child.
// Returns the updated context and the span. Call span.End() when the operation completes.
func Start(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *Span) {
	parent := spanFromContext(ctx)
	s := &Span{
		name:   name,
		start:  time.Now(),
		parent: parent,
		attrs:  attrs,
		ctx:    ctx,
	}
	if parent != nil {
		parent.children = append(parent.children, s)
	}
	return contextWithSpan(ctx, s), s
}

// RecordError marks the span as errored. Only the first non-nil error is stored;
// subsequent calls are no-ops. Call this before End() on error paths.
func (s *Span) RecordError(err error) {
	if err == nil || s.err != nil {
		return
	}
	s.err = err
}

// End completes the span. For root spans, emits a single DEBUG log line
// with the full timing tree. For child spans, records the duration only.
// Safe to call multiple times -- subsequent calls are no-ops.
func (s *Span) End() {
	if s.ended {
		return
	}
	s.ended = true
	s.duration = time.Since(s.start)

	// Only root spans emit log output
	if s.parent != nil {
		return
	}

	// Build log attributes: op, duration_ms, error flag, then child step durations.
	// Component is set via context so it appears exactly once in the log line.
	logCtx := logging.WithComponent(s.ctx, "perf")
	attrs := make([]any, 0, 3+2*len(s.children)+len(s.attrs))
	attrs = append(attrs, slog.String("op", s.name))
	attrs = append(attrs, slog.Int64("duration_ms", s.duration.Milliseconds()))
	if s.err != nil {
		attrs = append(attrs, slog.Bool("error", true))
	}

	// Add child step durations (and error flags) as flat keys
	for _, child := range s.children {
		// Auto-end children that were not explicitly ended
		if !child.ended {
			child.End()
		}
		key := fmt.Sprintf("steps.%s_ms", child.name)
		attrs = append(attrs, slog.Int64(key, child.duration.Milliseconds()))
		if child.err != nil {
			errKey := fmt.Sprintf("steps.%s_err", child.name)
			attrs = append(attrs, slog.Bool(errKey, true))
		}
	}

	// Add any extra attributes from Start()
	for _, a := range s.attrs {
		attrs = append(attrs, a)
	}

	logging.Debug(logCtx, "perf", attrs...)
}

