 28→// GetRewindPoints returns available rewind points.
 29→// Uses checkpoint.GitStore.ListTemporaryCheckpoints for reading from shadow branches.
 30→func (s *ManualCommitStrategy) GetRewindPoints(ctx context.Context, limit int) ([]RewindPoint, error) {
 31→	repo, err := OpenRepository(ctx)
 32→	if err != nil {
 33→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 34→	}
 35→
 36→	// Get checkpoint store
 37→	store, err := s.getCheckpointStore()
 38→	if err != nil {
 39→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
 40→	}
 41→
 42→	// Get current HEAD to find matching shadow branch
 43→	head, err := repo.Head()
 44→	if err != nil {
 45→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
 46→	}
 47→
 48→	// Find sessions for current HEAD
 49→	sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
 50→	if err != nil {
 51→		// Log error but continue to check for logs-only points
 52→		sessions = nil
 53→	}
 54→
 55→	var allPoints []RewindPoint
 56→
 57→	// Collect checkpoint points from active sessions using checkpoint.GitStore
 58→	// Cache session prompts by session ID to avoid re-reading the same prompt file
 59→	sessionPrompts := make(map[string]string)
 60→
 61→	for _, state := range sessions {
 62→		checkpoints, err := store.ListTemporaryCheckpoints(ctx, state.BaseCommit, state.WorktreeID, state.SessionID, limit)
 63→		if err != nil {
 64→			continue // Error reading checkpoints, skip this session
 65→		}
 66→
 67→		for _, cp := range checkpoints {
 68→			// Get session prompt (cached by session ID)
 69→			sessionPrompt, ok := sessionPrompts[cp.SessionID]
 70→			if !ok {
 71→				sessionPrompt = readSessionPrompt(repo, cp.CommitHash, cp.MetadataDir)
 72→				sessionPrompts[cp.SessionID] = sessionPrompt
 73→			}
 74→
 75→			allPoints = append(allPoints, RewindPoint{
 76→				ID:               cp.CommitHash.String(),
 77→				Message:          cp.Message,
 78→				MetadataDir:      cp.MetadataDir,
 79→				Date:             cp.Timestamp,
 80→				IsTaskCheckpoint: cp.IsTaskCheckpoint,
 81→				ToolUseID:        cp.ToolUseID,
 82→				SessionID:        cp.SessionID,
 83→				SessionPrompt:    sessionPrompt,
 84→				Agent:            state.AgentType,
 85→			})
 86→		}
 87→	}
 88→
 89→	// Sort by date, most recent first
 90→	sort.Slice(allPoints, func(i, j int) bool {
 91→		return allPoints[i].Date.After(allPoints[j].Date)
 92→	})
 93→
 94→	if len(allPoints) > limit {
 95→		allPoints = allPoints[:limit]
 96→	}
 97→
 98→	// Also include logs-only points from commit history
 99→	logsOnlyPoints, err := s.GetLogsOnlyRewindPoints(ctx, limit)
100→	if err == nil && len(logsOnlyPoints) > 0 {
101→		// Build set of existing point IDs for deduplication
102→		existingIDs := make(map[string]bool)
103→		for _, p := range allPoints {
104→			existingIDs[p.ID] = true
105→		}
106→
107→		// Add logs-only points that aren't already in the list
108→		for _, p := range logsOnlyPoints {
109→			if !existingIDs[p.ID] {
110→				allPoints = append(allPoints, p)
111→			}
112→		}
113→
114→		// Re-sort by date
115→		sort.Slice(allPoints, func(i, j int) bool {
116→			return allPoints[i].Date.After(allPoints[j].Date)
117→		})
118→
119→		// Re-trim to limit
120→		if len(allPoints) > limit {
121→			allPoints = allPoints[:limit]
122→		}
123→	}
124→
125→	return allPoints, nil
126→}
