453→// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
454→// This ensures that when the user commits after rewinding, the next checkpoint will only
455→// include prompts from the rewound point, not prompts from later checkpoints.
456→func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(ctx context.Context, repo *git.Repository, commit *object.Commit) error {
457→	// Extract session ID from the checkpoint commit's Entire-Session trailer
458→	sessionID, found := trailers.ParseSession(commit.Message)
459→	if !found {
460→		return errors.New("checkpoint has no Entire-Session trailer")
461→	}
462→
463→	// Load session state to get the shadow branch name
464→	state, err := s.loadSessionState(ctx, sessionID)
465→	if err != nil {
466→		return fmt.Errorf("failed to load session state: %w", err)
467→	}
468→	if state == nil {
469→		return fmt.Errorf("session %s not found", sessionID)
470→	}
471→
472→	// Reset the shadow branch to the checkpoint commit
473→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
474→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
475→
476→	// Update the reference to point to the checkpoint commit
477→	ref := plumbing.NewHashReference(refName, commit.Hash)
478→	if err := repo.Storer.SetReference(ref); err != nil {
479→		return fmt.Errorf("failed to update shadow branch: %w", err)
480→	}
481→
482→	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
483→	return nil
484→}
