494→// PreviewRewind returns what will happen if rewinding to the given point.
495→// This allows showing warnings about untracked files that will be deleted.
496→func (s *ManualCommitStrategy) PreviewRewind(ctx context.Context, point RewindPoint) (*RewindPreview, error) {
497→	// Logs-only points don't modify the working directory
498→	if point.IsLogsOnly {
499→		return &RewindPreview{}, nil
500→	}
501→
502→	repo, err := OpenRepository(ctx)
503→	if err != nil {
504→		return nil, fmt.Errorf("failed to open git repository: %w", err)
505→	}
506→
507→	// Get the checkpoint commit
508→	commitHash := plumbing.NewHash(point.ID)
509→	commit, err := repo.CommitObject(commitHash)
510→	if err != nil {
511→		return nil, fmt.Errorf("failed to get commit: %w", err)
512→	}
513→
514→	tree, err := commit.Tree()
515→	if err != nil {
516→		return nil, fmt.Errorf("failed to get tree: %w", err)
517→	}
518→
519→	// Load session state to get untracked files that existed at session start
520→	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
521→	var preservedUntrackedFiles map[string]bool
522→	if hasSessionTrailer {
523→		state, stateErr := s.loadSessionState(ctx, sessionID)
524→		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
525→			preservedUntrackedFiles = make(map[string]bool)
526→			for _, f := range state.UntrackedFilesAtStart {
527→				preservedUntrackedFiles[f] = true
528→			}
529→		}
530→	}
531→
532→	// Build set of files in the checkpoint tree (excluding metadata)
533→	checkpointFiles := make(map[string]bool)
534→	var filesToRestore []string
535→	err = tree.Files().ForEach(func(f *object.File) error {
536→		if err := ctx.Err(); err != nil {
537→			return err //nolint:wrapcheck // Propagating context cancellation
538→		}
539→		if !strings.HasPrefix(f.Name, entireDir) {
540→			checkpointFiles[f.Name] = true
541→			filesToRestore = append(filesToRestore, f.Name)
542→		}
543→		return nil
544→	})
545→	if err != nil {
546→		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
547→	}
548→
549→	// Get HEAD tree to identify tracked files
550→	head, err := repo.Head()
551→	if err != nil {
552→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
553→	}
554→	headCommit, err := repo.CommitObject(head.Hash())
555→	if err != nil {
556→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
557→	}
558→	headTree, err := headCommit.Tree()
559→	if err != nil {
560→		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
561→	}
562→
563→	// Build set of files tracked in HEAD
564→	trackedFiles := make(map[string]bool)
565→	//nolint:errcheck // Error is not critical for preview
566→	_ = headTree.Files().ForEach(func(f *object.File) error {
567→		if err := ctx.Err(); err != nil {
568→			return err //nolint:wrapcheck // Propagating context cancellation
569→		}
570→		trackedFiles[f.Name] = true
571→		return nil
572→	})
573→
574→	// Find untracked files that would be deleted.
575→	// Uses git ls-files to only consider non-ignored files.
576→	var filesToDelete []string
577→	untrackedNow, untrackedErr := collectUntrackedFiles(ctx)
578→	if untrackedErr != nil {
579→		fmt.Fprintf(os.Stderr, "Warning: could not list untracked files for preview: %v\n", untrackedErr)
580→		return &RewindPreview{
581→			FilesToRestore: filesToRestore,
582→			FilesToDelete:  filesToDelete,
583→		}, nil
584→	}
585→	for _, relPath := range untrackedNow {
586→		if checkpointFiles[relPath] {
587→			continue
588→		}
589→		if trackedFiles[relPath] {
590→			continue
591→		}
592→		if preservedUntrackedFiles[relPath] {
593→			continue
594→		}
595→		filesToDelete = append(filesToDelete, relPath)
596→	}
597→
598→	// Sort for consistent output
599→	sort.Strings(filesToRestore)
600→	sort.Strings(filesToDelete)
601→
602→	return &RewindPreview{
603→		FilesToRestore: filesToRestore,
604→		FilesToDelete:  filesToDelete,
605→	}, nil
606→}
607→
608→// RestoreLogsOnly restores session logs from a logs-only rewind point.
609→// This fetches the transcript from entire/checkpoints/v1 and writes it to the agent's session directory.
610→// Does not modify the working directory.
611→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
612→// If force is false, prompts for confirmation when local logs have newer timestamps.
613→// Returns info about each restored session so callers can print correct per-session resume commands.
614→func (s *ManualCommitStrategy) RestoreLogsOnly(ctx context.Context, point RewindPoint, force bool) ([]RestoredSession, error) {
615→	if !point.IsLogsOnly {
616→		return nil, errors.New("not a logs-only rewind point")
617→	}
618→
619→	if point.CheckpointID.IsEmpty() {
620→		return nil, errors.New("missing checkpoint ID")
621→	}
622→
623→	// Get checkpoint store
624→	store, err := s.getCheckpointStore()
625→	if err != nil {
626→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
627→	}
628→
629→	// Read checkpoint summary to get session count
630→	summary, err := store.ReadCommitted(ctx, point.CheckpointID)
631→	if err != nil {
632→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
633→	}
634→	if summary == nil {
635→		return nil, fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
636→	}
637→
638→	// Get worktree root for agent session directory lookup
639→	repoRoot, err := paths.WorktreeRoot(ctx)
640→	if err != nil {
641→		return nil, fmt.Errorf("failed to get worktree root: %w", err)
642→	}
643→
644→	// Check for newer local logs if not forcing
645→	if !force {
646→		sessions := s.classifySessionsForRestore(ctx, repoRoot, store, point.CheckpointID, summary)
647→		hasConflicts := false
648→		for _, sess := range sessions {
649→			if sess.Status == StatusLocalNewer {
650→				hasConflicts = true
651→				break
652→			}
653→		}
654→		if hasConflicts {
655→			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
656→			if promptErr != nil {
657→				return nil, promptErr
658→			}
659→			if !shouldOverwrite {
660→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
661→				return nil, nil
662→			}
663→		}
664→	}
665→
666→	// Count sessions to restore
667→	totalSessions := len(summary.Sessions)
668→	if totalSessions > 1 {
669→		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
670→	}
671→
672→	// Restore all sessions (oldest to newest, using 0-based indexing)
673→	var restored []RestoredSession
674→	for i := range totalSessions {
675→		content, readErr := store.ReadSessionContent(ctx, point.CheckpointID, i)
676→		if readErr != nil {
677→			fmt.Fprintf(os.Stderr, "  Warning: failed to read session %d: %v\n", i, readErr)
678→			continue
679→		}
680→		if content == nil || len(content.Transcript) == 0 {
681→			continue
682→		}
683→
684→		sessionID := content.Metadata.SessionID
685→		if sessionID == "" {
686→			fmt.Fprintf(os.Stderr, "  Warning: session %d has no session ID, skipping\n", i)
687→			continue
688→		}
689→
690→		// Resolve per-session agent from metadata — skip if agent is unknown
691→		if content.Metadata.Agent == "" {
692→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
693→			continue
694→		}
695→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
696→		if agErr != nil {
697→			fmt.Fprintf(os.Stderr, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
698→			continue
699→		}
700→
701→		// Compute transcript path from current repo location for cross-machine portability.
702→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
703→		if dirErr != nil {
704→			fmt.Fprintf(os.Stderr, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
705→			continue
706→		}
707→		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
708→
709→		// Get first prompt for display
710→		promptPreview := ExtractFirstPrompt(content.Prompts)
711→
712→		if totalSessions > 1 {
713→			isLatest := i == totalSessions-1
714→			if promptPreview != "" {
715→				if isLatest {
716→					fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", i+1, promptPreview)
717→				} else {
718→					fmt.Fprintf(os.Stderr, "  Session %d: %s\n", i+1, promptPreview)
719→				}
720→			}
721→			fmt.Fprintf(os.Stderr, "    Writing to: %s\n", sessionFile)
722→		} else {
723→			fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", sessionFile)
724→		}
725→
726→		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
727→		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
728→			fmt.Fprintf(os.Stderr, "    Warning: failed to create directory: %v\n", mkdirErr)
729→			continue
730→		}
731→
732→		agentSession := &agent.AgentSession{
733→			SessionID:  sessionID,
734→			AgentName:  sessionAgent.Name(),
735→			RepoPath:   repoRoot,
736→			SessionRef: sessionFile,
737→			NativeData: content.Transcript,
738→		}
739→		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
740→			if totalSessions > 1 {
741→				fmt.Fprintf(os.Stderr, "    Warning: failed to write session: %v\n", writeErr)
742→				continue
743→			}
744→			return nil, fmt.Errorf("failed to write session: %w", writeErr)
745→		}
746→
747→		restored = append(restored, RestoredSession{
748→			SessionID: sessionID,
749→			Agent:     sessionAgent.Type(),
750→			Prompt:    promptPreview,
751→			CreatedAt: content.Metadata.CreatedAt,
752→		})
753→	}
754→
755→	return restored, nil
756→}
757→
758→// ResolveAgentForRewind resolves the agent from checkpoint metadata.
759→func ResolveAgentForRewind(agentType types.AgentType) (agent.Agent, error) {
760→	ag, err := agent.GetByAgentType(agentType)
761→	if err != nil {
762→		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
763→	}
764→	return ag, nil
765→}
766→
767→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
768→// Returns an empty string if the prompt cannot be read.
769→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
770→	// Get the commit and its tree
771→	commit, err := repo.CommitObject(commitHash)
772→	if err != nil {
773→		return ""
774→	}
775→
776→	tree, err := commit.Tree()
777→	if err != nil {
778→		return ""
779→	}
780→
781→	// Look for prompt.txt in the metadata directory
782→	promptPath := metadataDir + "/" + paths.PromptFileName
783→	promptEntry, err := tree.File(promptPath)
784→	if err != nil {
785→		return ""
786→	}
787→
788→	content, err := promptEntry.Contents()
789→	if err != nil {
790→		return ""
791→	}
792→
793→	return ExtractFirstPrompt(content)
794→}
795→
796→// SessionRestoreStatus represents the status of a session being restored.
797→type SessionRestoreStatus int
798→
799→const (
800→	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
801→	StatusUnchanged                                   // Local and checkpoint are the same
802→	StatusCheckpointNewer                             // Checkpoint has newer entries
803→	StatusLocalNewer                                  // Local has newer entries (conflict)
804→)
805→
806→// SessionRestoreInfo contains information about a session being restored.
807→type SessionRestoreInfo struct {
808→	SessionID      string
809→	Prompt         string               // First prompt preview for display
810→	Status         SessionRestoreStatus // Status of this session
811→	LocalTime      time.Time
812→	CheckpointTime time.Time
813→}
814→
815→// classifySessionsForRestore checks all sessions in a checkpoint and returns info
816→// about each session, including whether local logs have newer timestamps.
817→// repoRoot is used to compute per-session agent directories.
818→// Sessions without agent metadata are skipped (cannot determine target directory).
819→func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store cpkg.Store, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
820→	var sessions []SessionRestoreInfo
821→
822→	totalSessions := len(summary.Sessions)
823→	// Check all sessions (0-based indexing)
824→	for i := range totalSessions {
825→		content, err := store.ReadSessionContent(ctx, checkpointID, i)
826→		if err != nil || content == nil || len(content.Transcript) == 0 {
827→			continue
828→		}
829→
830→		sessionID := content.Metadata.SessionID
831→		if sessionID == "" || content.Metadata.Agent == "" {
832→			continue
833→		}
834→
835→		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
836→		if agErr != nil {
837→			continue
838→		}
839→
840→		// Compute transcript path from current repo location for cross-machine portability.
841→		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
842→		if dirErr != nil {
843→			continue
844→		}
845→		localPath := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)
846→
847→		localTime := paths.GetLastTimestampFromFile(localPath)
848→		checkpointTime := paths.GetLastTimestampFromBytes(content.Transcript)
849→		status := ClassifyTimestamps(localTime, checkpointTime)
850→
851→		sessions = append(sessions, SessionRestoreInfo{
852→			SessionID:      sessionID,
853→			Prompt:         ExtractFirstPrompt(content.Prompts),
854→			Status:         status,
855→			LocalTime:      localTime,
856→			CheckpointTime: checkpointTime,
857→		})
858→	}
859→
860→	return sessions
861→}
862→
863→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
864→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
865→	// Local file doesn't exist (no timestamp found)
866→	if localTime.IsZero() {
867→		return StatusNew
868→	}
869→
870→	// Can't determine checkpoint time - treat as new/safe
871→	if checkpointTime.IsZero() {
872→		return StatusNew
873→	}
874→
875→	// Compare timestamps
876→	if localTime.After(checkpointTime) {
877→		return StatusLocalNewer
878→	}
879→	if checkpointTime.After(localTime) {
880→		return StatusCheckpointNewer
881→	}
882→	return StatusUnchanged
883→}
884→
885→// StatusToText returns a human-readable status string.
886→func StatusToText(status SessionRestoreStatus) string {
887→	switch status {
888→	case StatusNew:
889→		return "(new)"
890→	case StatusUnchanged:
891→		return "(unchanged)"
892→	case StatusCheckpointNewer:
893→		return "(checkpoint is newer)"
894→	case StatusLocalNewer:
895→		return "(local is newer)" // shouldn't appear in non-conflict list
896→	default:
897→		return ""
898→	}
899→}
900→
901→// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
902→// session logs that have newer timestamps than the checkpoint versions.
903→func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
904→	// Separate conflicting and non-conflicting sessions
905→	var conflicting, nonConflicting []SessionRestoreInfo
906→	for _, s := range sessions {
907→		if s.Status == StatusLocalNewer {
908→			conflicting = append(conflicting, s)
909→		} else {
910→			nonConflicting = append(nonConflicting, s)
911→		}
912→	}
913→
914→	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
915→	for _, info := range conflicting {
916→		// Show prompt if available, otherwise fall back to session ID
917→		if info.Prompt != "" {
918→			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
919→		} else {
920→			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
921→		}
922→		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
923→		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
924→	}
925→
926→	// Show non-conflicting sessions with their status
927→	if len(nonConflicting) > 0 {
928→		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
929→		for _, info := range nonConflicting {
930→			statusText := StatusToText(info.Status)
931→			if info.Prompt != "" {
932→				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
933→			} else {
934→				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
935→			}
936→		}
937→	}
938→
939→	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")
940→
941→	var confirmed bool
942→	form := huh.NewForm(
943→		huh.NewGroup(
944→			huh.NewConfirm().
945→				Title("Overwrite local session logs with checkpoint versions?").
946→				Value(&confirmed),
947→		),
948→	)
949→	if isAccessibleMode() {
950→		form = form.WithAccessible(true)
951→	}
952→
953→	if err := form.Run(); err != nil {
954→		if errors.Is(err, huh.ErrUserAborted) {
955→			return false, nil
956→		}
957→		return false, fmt.Errorf("failed to get confirmation: %w", err)
958→	}
959→
960→	return confirmed, nil
961→}
