// benchGitCmd runs a git command in the given directory for benchmark setup.
func benchGitCmd(b *testing.B, dir string, args ...string) string {
	b.Helper()
	//nolint:gosec // benchmark helper, args are from test code
	cmd := exec.CommandContext(context.Background(), "git", args...)
	cmd.Dir = dir
	output, err := cmd.CombinedOutput()
	if err != nil {
		b.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, output)
	}
	return strings.TrimSpace(string(output))
}

